import sys

def main():
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return
    n = int(data[0])
    first_set = set(map(int, data[1].split()))
    m = int(data[2])
    second_set = set(map(int, data[3].split()))
    inter = first_set & second_set
    if not inter:
        print("No common elements.")
    else:
        for x in sorted(inter):
            print(x)

